import { test, expect } from '@playwright/test';

test.describe('ZIP Code Auto-Formatting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should auto-format ZIP code as user types', async ({ page }) => {
    // Verify ZIP code input field exists
    const zipInput = page.getByLabel('ZIP Code');
    await expect(zipInput).toBeVisible();

    // Verify ZIP code input is empty initially
    await expect(zipInput).toHaveValue('');

    // Type the first digit of a valid ZIP code
    await zipInput.fill('1');
    await expect(zipInput).toHaveValue('1');

    // Type the second digit
    await zipInput.fill('2');
    await expect(zipInput).toHaveValue('12');

    // Type the third digit
    await zipInput.fill('3');
    await expect(zipInput).toHaveValue('123');

    // Type the fourth digit
    await zipInput.fill('4');
    await expect(zipInput).toHaveValue('1234');

    // Verify auto-formatting works for partial ZIP codes
    await zipInput.fill('5');
    await expect(zipInput).toHaveValue('12345');

