    await zipInput.fill('12345');
    await expect(zipInput).toHaveValue('12345');

    // Verify auto-formatting works for ZIP codes with spaces
    await zipInput.fill('12345');
    await expect(zipInput).toHaveValue('12345');

    // Verify auto-formatting works for ZIP codes with hyphens
    await zipInput.fill('123-45');
    await expect(zipInput).toHaveValue('123-45');

    // Verify auto-formatting works for ZIP codes with mixed characters
    await zipInput.fill('123-456');
    await expect(zipInput).toHaveValue('123-456');

    // Verify auto-formatting works for ZIP codes with leading zeros
    await zipInput.fill('01234');
    await expect(zipInput).toHaveValue('01234');

    // Verify auto-formatting works for ZIP codes with non-numeric characters
    await zipInput.fill('12345A');
    await expect(zipInput).toHaveValue('12345A');

